export type Locale = 'en' | 'pt';

const CATEGORY_LABELS: Record<string, Record<Locale, string>> = {
  All:      { en: 'All',           pt: 'Todas' },
  Live:     { en: 'Live',          pt: 'Ao Vivo' },
  School:   { en: 'School',        pt: 'Escola' },
  Explore:  { en: 'Explore',       pt: 'Explorar' },
  Create:   { en: 'Create',        pt: 'Criar' },
  Inspect:  { en: 'Inspect',       pt: 'Analisar' },
  Connect:  { en: 'Connect',       pt: 'Conectar' },
  Content:  { en: 'Content',       pt: 'Conteúdo' },
  Fun:      { en: 'Fun',           pt: 'Diversão' },
};

const UI_LABELS: Record<string, Record<Locale, string>> = {
  categories:   { en: 'Categories',                                       pt: 'Categorias' },
  tagline:      { en: 'Everything happening on the internet. In one place.', pt: 'Tudo o que acontece na internet. Num só lugar.' },
  searchApps:   { en: 'Search apps…',                                     pt: 'Pesquisar apps…' },
  openLauncher: { en: 'to open launcher',                                 pt: 'para abrir launcher' },
  pinned:       { en: 'Pinned',                                           pt: 'Fixos' },
  recentlyUsed: { en: 'Recently used',                                    pt: 'Usados recentemente' },
  noMatch:      { en: 'No apps match',                                    pt: 'Nenhuma app corresponde a' },
  open:         { en: 'Open',                                             pt: 'Abrir' },
};

export function categoryLabel(categoryId: string, locale: Locale): string {
  return CATEGORY_LABELS[categoryId]?.[locale] ?? categoryId;
}

export function t(key: string, locale: Locale): string {
  return UI_LABELS[key]?.[locale] ?? key;
}

const STORAGE_KEY = 'atlantis:locale';

export function loadLocale(): Locale {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'pt' || stored === 'en') return stored;
  } catch {}
  return 'en';
}

export function saveLocale(locale: Locale): void {
  try { localStorage.setItem(STORAGE_KEY, locale); } catch {}
}
