// ─── Component ────────────────────────────────────────────────────────────────

interface HomeScreenProps {
  apps: AppDefinition[];
  recentAppIds: string[];
  pinnedAppIds: string[];
  onTogglePin: (appId: string) => void;
  onSelect: (app: AppDefinition) => void;
  user?: { name?: string; email: string; avatarUrl?: string } | null;
  onSignOut?: () => void;
}

export function HomeScreen({ apps, recentAppIds, pinnedAppIds, onTogglePin, onSelect, user, onSignOut }: HomeScreenProps) {
  const [activeCategory, setActiveCategory] = useState('All');
  const [search, setSearch]                 = useState('');
  const [locale, setLocale]                 = useState<Locale>(loadLocale);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const toggleLocale = () => {
    const next: Locale = locale === 'en' ? 'pt' : 'en';
    setLocale(next);
    saveLocale(next);
  };

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return apps.filter((app) => {
      const meta = APP_META[app.id];
      const matchesCategory = activeCategory === 'All' || meta?.category === activeCategory;
      const matchesSearch = !q || app.label.toLowerCase().includes(q) || meta?.description.toLowerCase().includes(q);
      return matchesCategory && matchesSearch;
    });
  }, [apps, activeCategory, search]);

  const grouped = useMemo(() => {
    if (activeCategory !== 'All' || search) return null;
    const groups: Record<string, AppDefinition[]> = {};
    for (const app of filtered) {
      const cat = APP_META[app.id]?.category ?? 'Other';
      if (!groups[cat]) groups[cat] = [];
      groups[cat].push(app);
    }
    return groups;
  }, [filtered, activeCategory, search]);

  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = { All: apps.length };
    for (const app of apps) {
      const cat = APP_META[app.id]?.category;
      if (cat) counts[cat] = (counts[cat] ?? 0) + 1;
    }
    return counts;
  }, [apps]);

  const pinnedApps = useMemo(
    () => pinnedAppIds.flatMap((id) => apps.filter((a) => a.id === id)),
    [pinnedAppIds, apps],
  );
  const recentApps = useMemo(
    () => recentAppIds.flatMap((id) => apps.filter((a) => a.id === id)).slice(0, 6),
    [recentAppIds, apps],
  );

  let cardIndex = 0;

  const renderCard = (app: AppDefinition, idx: number) => {
    const meta = APP_META[app.id] ?? { icon: '🔲', description: '', descriptionPt: '', color: theme.colors.accent, category: '' };
    const isPinned = pinnedAppIds.includes(app.id);
    const desc = locale === 'pt' && meta.descriptionPt ? meta.descriptionPt : meta.description;
    return (
      <Card
        key={app.id}
        accentColor={meta.color}
        index={idx}
        pinned={isPinned}
        onClick={() => onSelect(app)}
      >
        <PinBtn
          className="pin-btn"
          pinned={isPinned}
          role="button"
          title={isPinned ? 'Unpin' : 'Pin to top'}
          onClick={(e) => { e.stopPropagation(); onTogglePin(app.id); }}
        >
          <Pin size={13} fill={isPinned ? 'currentColor' : 'none'} />
        </PinBtn>
        <CardIconWrap className="card-icon" style={{ background: `${meta.color}18` }}>
          {meta.icon}
        </CardIconWrap>
        <CardLabel>{app.label}</CardLabel>
        <CardDesc>{desc}</CardDesc>
        <CardFooter className="card-footer" accentColor={meta.color}>{t('open', locale)} &rarr;</CardFooter>
      </Card>
    );
  };

  return (
    <>
      <Page>
        <TopBar>
          <TopBarLeft>
            <TopBarLogo>Atl<span>antis</span></TopBarLogo>
          </TopBarLeft>
          <TopBarRight>
            <LocaleGroup>
              <LocaleBtn active={locale === 'pt'} onClick={() => { setLocale('pt'); saveLocale('pt'); }}>PT</LocaleBtn>
              <LocaleBtn active={locale === 'en'} onClick={() => { setLocale('en'); saveLocale('en'); }}>EN</LocaleBtn>
            </LocaleGroup>
            <ThemeToggle />
            {user && onSignOut && (
              <UserMenu
                user={{ name: user.name, email: user.email, avatarUrl: user.avatarUrl }}
                onSignOut={onSignOut}
              />
            )}
          </TopBarRight>
        </TopBar>
        <Body>
        <Sidebar>
          <SidebarHeading>{t('categories', locale)}</SidebarHeading>
          {ALL_CATEGORIES.map((cat) => (
            <SidebarItem key={cat} active={activeCategory === cat} onClick={() => setActiveCategory(cat)}>
              {categoryLabel(cat, locale)}
              <SidebarCount active={activeCategory === cat}>{categoryCounts[cat] ?? 0}</SidebarCount>
            </SidebarItem>
          ))}
        </Sidebar>

        <Main>
          <Header>
            <Tagline>{t('tagline', locale)}</Tagline>
            <SearchRow>
              <SearchWrap>
                <SearchInput
                  ref={searchInputRef}
                  placeholder={t('searchApps', locale)}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <SearchIcon><Search size={15} /></SearchIcon>
              </SearchWrap>
              <KbdHint>
                <kbd>⌘</kbd><kbd>K</kbd> {t('openLauncher', locale)}
              </KbdHint>
            </SearchRow>
          </Header>

          {filtered.length === 0 && (
            <EmptyState>{t('noMatch', locale)} &ldquo;{search}&rdquo;</EmptyState>
          )}

          {!search && activeCategory === 'All' && (
            <FeaturedCard onClick={() => onSelect(apps.find((a) => a.id === 'techscope') ?? apps[0])}>
              <FeaturedLeft>
                <FeaturedBadge>
                  <FeaturedDot />
                  Live &middot; Internet Control Panel
                </FeaturedBadge>
                <FeaturedTitle>📡 TechScope</FeaturedTitle>
                <FeaturedSub>GitHub trending &middot; HN Front Page &middot; AI Radar &middot; Experiment Zone &middot; npm Pulse</FeaturedSub>
                <FeaturedOpen>Open &rarr;</FeaturedOpen>
              </FeaturedLeft>
              <FeaturedFeeds>
                {TECHSCOPE_FEEDS.map((feed) => (
                  <FeedPill key={feed}>{feed}</FeedPill>
                ))}
              </FeaturedFeeds>
            </FeaturedCard>
          )}

          {!search && pinnedApps.length > 0 && (
            <div>
              <SectionLabel>{t('pinned', locale)}</SectionLabel>
              <Grid>
                {pinnedApps.map((app) => renderCard(app, cardIndex++))}
              </Grid>
            </div>
          )}

          {!search && activeCategory === 'All' && recentApps.length > 0 && (
            <div>
              <SectionLabel>{t('recentlyUsed', locale)}</SectionLabel>
              <Grid>
                {recentApps.map((app) => renderCard(app, cardIndex++))}
              </Grid>
            </div>
          )}

          {grouped ? (
            Object.entries(grouped).map(([category, catApps]) => (
              <div key={category}>
                <SectionLabel>{categoryLabel(category, locale)}</SectionLabel>
                <Grid>
                  {catApps.map((app) => renderCard(app, cardIndex++))}
                </Grid>
              </div>
            ))
          ) : (
            <Grid>
              {filtered.map((app) => renderCard(app, cardIndex++))}
            </Grid>
          )}
        </Main>
        </Body>
      </Page>
    </>
  );
}
